@using sv_2591c93db1274c9587fa82290fa50d35.Models

<div class="step-content">
    <h3>References</h3>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm Reference="@References[index]"
                           CanRemove="@(References.Count > 1)"
                           OnReferenceChanged="r => UpdateReference(index, r)"
                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Model { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string? ValidationMessage;

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Count > 0)
        {
            References = Model.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        References[index] = reference;
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
            References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new Reference("", "", "", ""));
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email))
            {
                ValidationMessage = "Each reference must have at least a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(References.ToList());
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}

