@using sv_2591c93db1274c9587fa82290fa50d35.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (Submitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl>
                    <dt>Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")</span>
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-summary">@ErrorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool Submitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            Submitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}

