@page "/apply"
@using sv_2591c93db1274c9587fa82290fa50d35.Models
@using sv_2591c93db1274c9587fa82290fa50d35.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              OnNext="OnPersonalInfoNext"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Model="@workHistory"
                             OnNext="OnWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Model="@references"
                            OnNext="OnReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep Model="@coverLetter"
                             OnNext="OnCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        Work="@workHistory"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void OnPersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void OnWorkHistoryNext(WorkHistory work)
    {
        workHistory = work;
        currentStep = 2;
    }

    private void OnReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void OnCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo!,
            workHistory!,
            references!,
            coverLetter!
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 2rem;
}

.application-form h2 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    border-color: #dee2e6;
    background: #f8f9fa;
    color: #adb5bd;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    color: #adb5bd;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
}

.step-connector.completed {
    background: #198754;
}

/* Form Elements */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h3 {
    margin-bottom: 1.5rem;
    color: #333;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #444;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: 400 !important;
    margin-top: 0.5rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    padding: 0.6rem 1.5rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    padding: 0.6rem 1.5rem;
    background: #fff;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-outline:hover {
    background: #e7f1ff;
}

.btn-secondary {
    padding: 0.5rem 1rem;
    background: #f8f9fa;
    color: #495057;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-remove {
    padding: 0.3rem 0.8rem;
    background: #fff;
    color: #dc3545;
    border: 1px solid #dc3545;
    border-radius: 4px;
    font-size: 0.85rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove:hover {
    background: #dc3545;
    color: #fff;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #0b5ed7;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
    font-weight: 600;
}

/* Entry Cards */
.entry-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.entry-card h4 {
    margin: 0 0 1rem 0;
    font-size: 0.95rem;
    color: #555;
}

/* Validation */
.validation-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #fff3cd;
    border: 1px solid #ffecb5;
    color: #664d03;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding: 1rem 0;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h4 {
    margin: 0;
    color: #333;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0.75rem 0 0 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin: 0.75rem 0;
    padding-left: 0.5rem;
    border-left: 3px solid #e9ecef;
}

.review-entry p {
    margin: 0.25rem 0 0 0;
    color: #555;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h4 {
    color: #198754;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.1rem;
    color: #555;
}

