+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafbfc;
+}
+
+.entry-card h4 {
+    margin: 0 0 1rem 0;
+    font-size: 0.95rem;
+    color: #555;
+}
+
+/* Validation */
+.validation-error {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+.validation-summary {
+    background: #fff3cd;
+    border: 1px solid #ffecb5;
+    color: #664d03;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-top: 1rem;
+    font-size: 0.9rem;
+}
+
+/* Character Count */
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.25rem;
+}
+
+/* Review Step */
+.review-section {
+    border-bottom: 1px solid #eee;
+    padding: 1rem 0;
+}
+
+.review-section:last-of-type {
+    border-bottom: none;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.review-header h4 {
+    margin: 0;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0.75rem 0 0 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-entry {
+    margin: 0.75rem 0;
+    padding-left: 0.5rem;
+    border-left: 3px solid #e9ecef;
+}
+
+.review-entry p {
+    margin: 0.25rem 0 0 0;
+    color: #555;
+    font-size: 0.9rem;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h4 {
+    color: #198754;
+    font-size: 1.5rem;
+    margin-bottom: 1rem;
+}
+
+.confirmation p {
+    font-size: 1.1rem;
+    color: #555;
+}
+

