    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Reference.Name" @onchange="e => Update(Reference with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Reference.Relationship" @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Reference.Email" @onchange="e => Update(Reference with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Reference.Phone" @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

